<?php
if (session_status() === PHP_SESSION_NONE) session_start();
if (!isset($_SESSION['user_id'])) { header('Location: index.php'); exit(); }
$page_title='Sales Reports'; require_once 'config/database.php';
$period=$_GET['period']??'daily'; if(!in_array($period,['daily','monthly','yearly'],true))$period='daily';
$date=$_GET['date']??date('Y-m-d'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');
$month=$_GET['month']??date('Y-m'); if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');
$year=(int)($_GET['year']??date('Y')); if($year<2000||$year>2100)$year=(int)date('Y');
$labels=[];$values=[];$report_title='';$report_subtitle='';$grand_total=0;$transaction_count=0;$avg=0;
if($period==='daily'){
    $report_title='Daily Sales Report';$report_subtitle=date('F d, Y',strtotime($date));
    // The existing sales table stores sale_date as DATE, so the daily report lists that day's transactions.
    $stmt=$conn->prepare('SELECT sale_id,total_amount FROM sales WHERE sale_date=? ORDER BY sale_id');$stmt->bind_param('s',$date);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc()){$labels[]='Sale #'.$row['sale_id'];$values[]=(float)$row['total_amount'];$grand_total+=(float)$row['total_amount'];$transaction_count++;}$stmt->close();
}elseif($period==='monthly'){
    $report_title='Monthly Sales Report';$report_subtitle=date('F Y',strtotime($month.'-01'));
    $stmt=$conn->prepare("SELECT DAY(sale_date) d, COALESCE(SUM(total_amount),0) total, COUNT(*) cnt FROM sales WHERE DATE_FORMAT(sale_date,'%Y-%m')=? GROUP BY DAY(sale_date) ORDER BY d");$stmt->bind_param('s',$month);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc()){$labels[]='Day '.$row['d'];$values[]=(float)$row['total'];$grand_total+=(float)$row['total'];$transaction_count+=(int)$row['cnt'];}$stmt->close();
}else{
    $report_title='Yearly Sales Report';$report_subtitle=(string)$year;
    $stmt=$conn->prepare("SELECT MONTH(sale_date) m, COALESCE(SUM(total_amount),0) total, COUNT(*) cnt FROM sales WHERE YEAR(sale_date)=? GROUP BY MONTH(sale_date) ORDER BY m");$stmt->bind_param('i',$year);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc()){$labels[]=date('M',mktime(0,0,0,(int)$row['m'],1));$values[]=(float)$row['total'];$grand_total+=(float)$row['total'];$transaction_count+=(int)$row['cnt'];}$stmt->close();
}
$avg=$transaction_count?$grand_total/$transaction_count:0;
$topSql="SELECT p.product_name, SUM(sd.quantity) qty, SUM(sd.subtotal) revenue FROM sales_details sd JOIN products p ON p.product_id=sd.product_id JOIN sales s ON s.sale_id=sd.sale_id ";
if($period==='daily'){$topSql.="WHERE s.sale_date='".$conn->real_escape_string($date)."' ";}elseif($period==='monthly'){$topSql.="WHERE DATE_FORMAT(s.sale_date,'%Y-%m')='".$conn->real_escape_string($month)."' ";}else{$topSql.="WHERE YEAR(s.sale_date)=".(int)$year." ";}$topSql.='GROUP BY sd.product_id ORDER BY revenue DESC LIMIT 5';$top=$conn->query($topSql);
include 'includes/header.php';
?>
<div class="page-header"><div><h2>Sales Reports</h2><p>Review actual sales transactions by day, month, or year.</p></div><button class="btn-primary" onclick="window.print()"><i class="fa-solid fa-print"></i> Print Report</button></div>
<div class="report-tabs"><a class="report-tab <?php echo $period==='daily'?'active':''; ?>" href="sales_report.php?period=daily">Daily</a><a class="report-tab <?php echo $period==='monthly'?'active':''; ?>" href="sales_report.php?period=monthly">Monthly</a><a class="report-tab <?php echo $period==='yearly'?'active':''; ?>" href="sales_report.php?period=yearly">Yearly</a></div>
<form class="report-filter-card" method="get"><input type="hidden" name="period" value="<?php echo $period; ?>"><?php if($period==='daily'): ?><div><label>Date</label><input type="date" name="date" value="<?php echo htmlspecialchars($date); ?>"></div><?php elseif($period==='monthly'): ?><div><label>Month</label><input type="month" name="month" value="<?php echo htmlspecialchars($month); ?>"></div><?php else: ?><div><label>Year</label><select name="year"><?php for($y=(int)date('Y');$y>=2020;$y--): ?><option value="<?php echo $y; ?>" <?php echo $year===$y?'selected':''; ?>><?php echo $y; ?></option><?php endfor; ?></select></div><?php endif; ?><button class="btn-primary"><i class="fa-solid fa-filter"></i> Generate</button></form>
<div class="report-kpis"><div class="report-kpi"><span>Total Sales</span><strong>₱<?php echo number_format($grand_total,2); ?></strong><small><?php echo htmlspecialchars($report_subtitle); ?></small></div><div class="report-kpi"><span>Transactions</span><strong><?php echo $transaction_count; ?></strong><small>Recorded sales</small></div><div class="report-kpi"><span>Average Sale</span><strong>₱<?php echo number_format($avg,2); ?></strong><small>Per transaction</small></div></div>
<div class="report-grid"><div class="dashboard-panel report-chart-panel"><div class="dashboard-panel-header"><div><h3><?php echo htmlspecialchars($report_title); ?></h3><p>Sales trend for the selected period</p></div></div><div style="height:320px;padding:15px 20px 25px"><canvas id="salesChart"></canvas></div></div><div class="dashboard-panel"><div class="dashboard-panel-header"><div><h3>Top Products</h3><p>Highest revenue within the selected period</p></div></div><div class="top-products-list"><?php if($top && $top->num_rows): while($p=$top->fetch_assoc()): ?><div class="top-product"><div class="top-product-icon"><i class="fa-solid fa-bread-slice"></i></div><div><strong><?php echo htmlspecialchars($p['product_name']); ?></strong><small><?php echo (int)$p['qty']; ?> units sold</small></div><b>₱<?php echo number_format($p['revenue'],2); ?></b></div><?php endwhile; else: ?><div class="no-data">No product sales for this period.</div><?php endif; ?></div></div></div>
<div class="table-container report-table"><div class="table-header"><div><h3>Report Summary</h3><p>Actual totals from the sales table.</p></div></div><div class="table-wrapper"><table><thead><tr><th>Period</th><th>Sales</th><th>Share</th></tr></thead><tbody><?php if($values): foreach($values as $i=>$v): ?><tr><td><?php echo htmlspecialchars($labels[$i]); ?></td><td><strong>₱<?php echo number_format($v,2); ?></strong></td><td><?php echo $grand_total>0?number_format(($v/$grand_total)*100,1):'0.0'; ?>%</td></tr><?php endforeach; else: ?><tr><td colspan="3" class="no-data">No sales records for the selected period.</td></tr><?php endif; ?></tbody></table></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<script>const labels=<?php echo json_encode($labels); ?>, values=<?php echo json_encode($values); ?>;new Chart(document.getElementById('salesChart'),{type:'bar',data:{labels:labels,datasets:[{label:'Sales (₱)',data:values,borderRadius:7,backgroundColor:'rgba(155,79,34,.82)',borderColor:'rgba(155,79,34,1)',borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>' ₱'+Number(c.raw).toLocaleString(undefined,{minimumFractionDigits:2})}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'₱'+Number(v).toLocaleString()}},x:{grid:{display:false}}}}});</script>
<?php include 'includes/footer.php'; ?>
